node --no-warnings -e "
const {DatabaseSync}=require('node:sqlite');
const db=new DatabaseSync('.codegraph/codegraph.db');
const q=\`
SELECT n.name, n.qualified_name, n.kind, n.file_path, n.start_line,
       COUNT(DISTINCT e.source) AS callers, COUNT(*) AS call_edges
FROM nodes n
JOIN edges e ON e.target=n.id AND e.kind='calls'
WHERE n.file_path LIKE 'internal/%' AND n.kind IN ('function','method')
GROUP BY n.id
ORDER BY callers DESC
LIMIT 20\`;
for(const r of db.prepare(q).all())
  console.log(String(r.callers).padStart(3), '('+r.call_edges+'e)', r.kind, r.name, '::', r.qualified_name, '@', r.file_path+':'+r.start_line);
"

