  const t=db.prepare(\"SELECT id,file_path,start_line FROM nodes WHERE qualified_name=? AND file_path LIKE 'internal/%' LIMIT 1\").get(qn);
  if(!t){console.log(qn,'NOT FOUND');continue;}
  const rows=db.prepare(\"SELECT s.file_path fp, count(*) c FROM edges e JOIN nodes s ON s.id=e.source WHERE e.target=? AND e.kind='calls' GROUP BY s.file_path ORDER BY c DESC\").all(t.id);
  const nonTest=rows.filter(r=>!r.fp.endsWith('_test.go'));
  const testFiles=rows.filter(r=>r.fp.endsWith('_test.go'));
  console.log('=== '+qn+' @ '+t.file_path+':'+t.start_line+' | distinct files='+rows.length+' | nonTest files='+nonTest.length);
  for(const r of rows.slice(0,8)) console.log('   ',String(r.c).padStart(3),r.fp);
}
